class Solution {
public:
    int maximumGroups(vector<int>& grades) {
        long long n = grades.size();
        long long s = sqrtl(8.0L * n + 1);
        while (s * s > 8 * n + 1) s--;
        while ((s + 1) * (s + 1) <= 8 * n + 1) s++;
        return (int)((s - 1) / 2);
    }
};

